# November 23, 2026: a third scatter of places across Manitoba (37 so far), the thinnest state or province on the map,
# claimed with tools/choose.py --claim --thinnest. Sources opened in this session: the Manitoba Historical Society's
# "Historic Sites of Manitoba" page for each place (mhs.mb.ca, read with tools/page.py; each gives a site coordinate),
# the Province's Provincial Heritage Site page for Camp Hughes (gov.mb.ca/chc/hrb), the Parks Canada directory entry for
# Camp Hughes, the Town of Carberry's page, Manitoba Parks' Asessippi park guide, and a web search for Ross House hours.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def MHS(t,s): return ['Manitoba Historical Society: '+t,'https://mhs.mb.ca/docs/sites/'+s+'.shtml']

